package net.minecraft.world.entity;import net.minecraft.world.level.Level;import net.minecraft.world.entity.ai.navigation.PathNavigation;import net.minecraft.world.entity.ai.control.LookControl;public class Mob extends LivingEntity{public LivingEntity target;public boolean aggressive,visible=true;public PathNavigation nav=new PathNavigation();public LookControl look=new LookControl();public Mob(Level l){super(l);}public void tick(){tickCount++;}public LivingEntity getTarget(){return target;}public void setTarget(LivingEntity t){target=t;}public boolean hasLineOfSight(Entity e){return visible;}public void setAggressive(boolean a){aggressive=a;}public boolean isAggressive(){return aggressive;}public PathNavigation getNavigation(){return nav;}public LookControl getLookControl(){return look;}}